import{f as s,o as n,c as e,a2 as p}from"./chunks/framework.Cd9rfTEn.js";const b=JSON.parse('{"title":"Prompt autocontenido para Claude — imágenes IMG-C01 a IMG-C12","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-PROMPT-CLAUDE-COMPLETO.md","filePath":"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-PROMPT-CLAUDE-COMPLETO.md","lastUpdated":null}'),l={name:"presentacion-stakeholders/comparativo-funcional-procoop-vs-coopapps-PROMPT-CLAUDE-COMPLETO.md"};function o(r,a,i,c,t,u){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="prompt-autocontenido-para-claude-—-imagenes-img-c01-a-img-c12" tabindex="-1">Prompt autocontenido para Claude — imágenes IMG-C01 a IMG-C12 <a class="header-anchor" href="#prompt-autocontenido-para-claude-—-imagenes-img-c01-a-img-c12" aria-label="Permalink to &quot;Prompt autocontenido para Claude — imágenes IMG-C01 a IMG-C12&quot;">​</a></h1><p><strong>Uso:</strong> copiar todo el bloque <code>\`\`\`text</code> de la sección 1 y pegarlo en Claude.<br><strong>Opcional:</strong> adjuntar solo si vas a generar <strong>IMG-C13–C24</strong> o si querés verificación extra del comparativo completo.</p><hr><h2 id="_1-bloque-para-pegar-en-claude" tabindex="-1">1. Bloque para pegar en Claude <a class="header-anchor" href="#_1-bloque-para-pegar-en-claude" aria-label="Permalink to &quot;1. Bloque para pegar en Claude&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sos mi diseñador de presentación ejecutiva (1920×1080, 16:9) para directivos de cooperativas de servicios públicos de Argentina. Producto: CoopApps (SaaS). Referencia: ProCoop (escritorio).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Este mensaje incluye REGLAS + CONTENIDO de cada slide IMG-C01…C12. Usá SOLO lo que figura acá. No inventes cifras ni promesas.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== REGLAS VISUALES ===</span></span>
<span class="line"><span>- Español de Argentina, formal, sin &quot;revolucionario/disruptivo&quot;.</span></span>
<span class="line"><span>- ProCoop: respeto; &quot;Hoy&quot; en grises #E5E7EB / texto #6B7280.</span></span>
<span class="line"><span>- CoopApps: acento #2E7D32; títulos #2F343A; fondo #FFFFFF.</span></span>
<span class="line"><span>- Ámbar #B7791F: solo viñeta &quot;API de sus datos (plan O11)&quot; en IMG-C06 y si repites API.</span></span>
<span class="line"><span>- Cada slide: artefacto HTML+SVG 1920×1080, exportable a PNG. NO generador de imágenes si hay números.</span></span>
<span class="line"><span>- Tipografía sans (Inter); título grande; máx. 4 viñetas; íconos línea simples; mucho aire.</span></span>
<span class="line"><span>- Datos ficticios: &quot;Cooperativa A&quot;. Sin DNI/CUIT reales.</span></span>
<span class="line"><span>- Tras cada slide, en chat: notas Gerencia (3 líneas) + números citados.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== NÚMEROS AUTORIZADOS (no uses otros) ===</span></span>
<span class="line"><span>- Menú ProCoop relevado: 120 funciones; con destino en CoopApps: 119 (112 absorbidas, 7 reemplazadas, 1 descartada &quot;administrar BD&quot;, 0 sin destino).</span></span>
<span class="line"><span>- DEMO facturación: ~12.500 comprobantes por emisión mensual (referencia volumen).</span></span>
<span class="line"><span>- Módulos especificación: 19 funcionales M01–M19 + 12 transversales T01–T12.</span></span>
<span class="line"><span>- Requisitos: 4.213 funcionales; 293 no funcionales (aprox., especificación vigente).</span></span>
<span class="line"><span>- Olas construcción: O0 a O11 (12 olas); mapa de contenido (DEC-118; build vía pipeline GoodApps, no Cursor).</span></span>
<span class="line"><span>- Stack vigente: .NET 10, Azure SQL, React 19, Microsoft Azure (DEC-111–112).</span></span>
<span class="line"><span>- Familias de servicio con ficha: 17.</span></span>
<span class="line"><span>- Roles plantilla: 40.</span></span>
<span class="line"><span>- Corte comercial piloto: ola O7; corte administrativo ProCoop: ola O11 (DEC-089).</span></span>
<span class="line"><span>- API externa documentada para la cooperativa: planificada O11; antes exportaciones y reportes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PROHIBIDO EN TEXTO VISIBLE ===</span></span>
<span class="line"><span>&quot;Mismas pantallas&quot;; &quot;API desde el día 1&quot;; &quot;sin ProCoop&quot;; &quot;reemplazo inmediato&quot;; &quot;tiempo real al milisegundo&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== CATÁLOGO DE SLIDES (generá solo la que pida; si pido &quot;las 12&quot;, una por mensaje) ===</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C01 PORTADA</span></span>
<span class="line"><span>Título: CoopApps y su cooperativa: mismo negocio, nueva plataforma.</span></span>
<span class="line"><span>Subtítulo: Comparativo funcional respecto de ProCoop.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C02 RESPETO</span></span>
<span class="line"><span>Título: ProCoop hace mucho. Y lo hace bien.</span></span>
<span class="line"><span>Viñetas: Facturación masiva · Multiservicio · Mora, compras, sueldos · Confianza de años.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C03 COBERTURA MENÚ (número protagonista)</span></span>
<span class="line"><span>Título: Lo que ProCoop hace hoy → cubierto en CoopApps.</span></span>
<span class="line"><span>Número grande: 119 de 120</span></span>
<span class="line"><span>Subtexto: funciones del menú relevado con destino en la especificación.</span></span>
<span class="line"><span>Pie: La restante es administrar la base de datos; en la nube lo hace la plataforma.</span></span>
<span class="line"><span>Opcional secundario (texto chico): 112 equivalentes · 7 con mecanismo mejor · 0 sin destino.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C04 OCHO APLICACIONES</span></span>
<span class="line"><span>Título: Una cooperativa, ocho formas de trabajar.</span></span>
<span class="line"><span>Centro: Una sola información.</span></span>
<span class="line"><span>Alrededor (8 etiquetas): Gestión web · App del socio (su marca) · Campo sin señal · Empleados · Sitio público · Tótem · Plataforma (proveedor) · Integraciones de datos.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C05 SOCIO (antes/después)</span></span>
<span class="line"><span>Título: El socio ve lo mismo que ve caja.</span></span>
<span class="line"><span>Columna Hoy: Portal sobre copia sincronizada (CoopOnline).</span></span>
<span class="line"><span>Columna Con CoopApps: Contratar, pagar, reclamar y dar de baja desde el celular con la marca de la cooperativa.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C06 SIETE DOLORES</span></span>
<span class="line"><span>Título: Siete dolores, siete respuestas en especificación.</span></span>
<span class="line"><span>Viñetas: Nube · Sin servidores propios · API de sus datos (plan O11) [etiqueta ámbar opcional] · App del socio · Su marca · Seguridad verificable · Soporte con caso y registro.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C07 FACTURACIÓN Y COBRANZA</span></span>
<span class="line"><span>Título: Facturar y cobrar con control.</span></span>
<span class="line"><span>Viñetas: Lotes con excepciones visibles · Un solo cálculo de intereses · Pago confirmado antes de reconectar · Sin guardar números de tarjeta.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C08 TÉCNICA Y CAMPO</span></span>
<span class="line"><span>Título: Del turno a la conformidad, en un solo flujo.</span></span>
<span class="line"><span>Viñetas: Factibilidad · Visita con estado visible al socio · Una app: técnico, lecturista y cobrador · Equipos rastreados por serie.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C09 LO NUEVO</span></span>
<span class="line"><span>Título: Lo que suma, más allá de reemplazar pantallas.</span></span>
<span class="line"><span>Viñetas: Institucional y asambleas · Comunidad y avisos por zona · Diccionario propio (socio/asociado) · Expediente digital · Indicadores iguales en todo canal.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C10 DIEcisiete SERVICIOS</span></span>
<span class="line"><span>Título: Electricidad, gas, agua… y también sepelio, cementerio, vivienda.</span></span>
<span class="line"><span>Texto: Cada servicio con sus reglas; la ley no se apaga con un parámetro.</span></span>
<span class="line"><span>Dato visible: 17 familias de servicio.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C11 MIGRACIÓN</span></span>
<span class="line"><span>Título: Cambio por etapas.</span></span>
<span class="line"><span>Viñetas: Convivencia con ProCoop · Comparar factura a factura · Dos ciclos conciliados · Códigos de barras antiguos válidos en transición.</span></span>
<span class="line"><span>Números: 12 olas (O0–O11) · 172 prompts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMG-C12 CHECKLIST CIERRE</span></span>
<span class="line"><span>Título: ¿Qué pueden validar hoy?</span></span>
<span class="line"><span>Seis ítems con check visual: Menú cubierto (119/120) · Multiservicio y tasas terceros · Socio paga y reclama · Mora con norma · Migración por etapas · Datos exportables.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== CÓMO RESPONDÉ ===</span></span>
<span class="line"><span>Si escribo &quot;Generá IMG-C03&quot;:</span></span>
<span class="line"><span>1) HTML/SVG 1920×1080 con textos exactos de IMG-C03 arriba.</span></span>
<span class="line"><span>2) En chat: Gerencia (continuidad operativa; riesgo &quot;perdemos módulo&quot; acotado) + lista de números usados.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Confirmá lectura de estas reglas y esperá: &quot;Generá IMG-C01&quot; o el código que pida.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br><span class="line-number">78</span><br><span class="line-number">79</span><br><span class="line-number">80</span><br><span class="line-number">81</span><br><span class="line-number">82</span><br><span class="line-number">83</span><br><span class="line-number">84</span><br><span class="line-number">85</span><br><span class="line-number">86</span><br><span class="line-number">87</span><br><span class="line-number">88</span><br><span class="line-number">89</span><br><span class="line-number">90</span><br><span class="line-number">91</span><br><span class="line-number">92</span><br></div></div><hr><h2 id="_2-¿alcanza-sin-adjuntar-archivos" tabindex="-1">2. ¿Alcanza sin adjuntar archivos? <a class="header-anchor" href="#_2-¿alcanza-sin-adjuntar-archivos" aria-label="Permalink to &quot;2. ¿Alcanza sin adjuntar archivos?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Alcance</th><th>¿Solo con este prompt?</th></tr></thead><tbody><tr><td><strong>IMG-C01 a IMG-C12</strong> (bloque comparativo corto)</td><td><strong>Sí</strong> — textos y números clave van inline arriba.</td></tr><tr><td><strong>IMG-C13 a IMG-C24</strong></td><td><strong>No</strong> — adjuntar <code>comparativo-funcional-procoop-vs-coopapps-para-presentacion.md</code> §2.</td></tr><tr><td><strong>Deck unificada</strong> (IMG-01, IMG-D, etc.)</td><td><strong>No</strong> — adjuntar <code>documento-base-presentacion.md</code> y <code>dolores-procoop-antes-y-despues.md</code>.</td></tr><tr><td>Q&amp;A técnica profunda (120 ítems PC)</td><td>Adjuntar <code>comparativo-funcional-procoop-vs-coopapps.md</code>.</td></tr></tbody></table><hr><h2 id="_3-relacion-con-el-prompt-§0-2-de-la-guia" tabindex="-1">3. Relación con el prompt §0.2 de la guía <a class="header-anchor" href="#_3-relacion-con-el-prompt-§0-2-de-la-guia" aria-label="Permalink to &quot;3. Relación con el prompt §0.2 de la guía&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Archivo</th><th>Rol</th></tr></thead><tbody><tr><td><code>comparativo-funcional-procoop-vs-coopapps-para-presentacion.md</code> §0.2</td><td>Reglas + códigos; <strong>requiere adjuntos</strong> para el contenido.</td></tr><tr><td><strong>Este archivo</strong></td><td>Mismo rol + <strong>contenido C01–C12 embebido</strong>; listo para pegar solo.</td></tr></tbody></table>`,11)])])}const m=s(l,[["render",o]]);export{b as __pageData,m as default};
